-- ─────────────────────────────────────────────
-- MARKS — final exam bulk for remaining courses
-- ─────────────────────────────────────────────

INSERT INTO marks (student_id, course_id, exam_type, mark, entered_by)
SELECT sc.student_id, sc.course_id, 'final',
       CASE
           WHEN sc.student_id % 5 = 0 THEN 58
           WHEN sc.student_id % 4 = 0 THEN 64
           WHEN sc.student_id % 3 = 0 THEN 72
           WHEN sc.student_id % 2 = 0 THEN 48
           ELSE 81
       END,
       3
FROM student_courses sc
JOIN courses c ON sc.course_id = c.id
WHERE c.course_code IN ('ICT2113','ICT2122','ICT2142','ICT2152')
  AND sc.student_id BETWEEN 14 AND 23;

-- ─────────────────────────────────────────────
-- HOW TO USE course_sessions IN THE MEDICALS PANEL
-- ─────────────────────────────────────────────
--
-- In MedicalsPanel.java (or MedicalDAO), when the student
-- selects a course and types/selects a session number, run:
--
--   SELECT session_date, session_type
--   FROM course_sessions
--   WHERE course_id = ?        -- selected course id
--     AND session_number = ?   -- entered session number
--
-- Then auto-populate the date field in the form.
-- This ensures session_date in medicals is always accurate
-- and the student cannot enter a wrong date.
-- ─────────────────────────────────────────────
